namespace Showcase.Web.Client.Models;

/// <summary>
/// One entry per color palette in <c>Blazor/wwwroot/css/scss/_palettes.scss</c>, in
/// the same order as <c>Blazor/.themes/README.md</c>'s table (that folder is
/// gitignored/local-only design reference — this is its live-app equivalent: one
/// route per palette instead of one static .md/.html pair per palette, structured
/// the same way that reference folder's <c>index.html</c>/<c>&lt;slug&gt;.html</c>
/// pair is — a swatch-strip card grid on the index, every <c>--fa-*</c> token
/// swatched on the detail page).
/// </summary>
public static class PaletteCatalog
{
    /// <summary>
    /// <see cref="Light"/>/<see cref="Dark"/> are literal copies of that palette's
    /// <c>--fa-*</c> custom properties from <c>_palettes.scss</c> (keyed without the
    /// <c>--fa-</c> prefix, e.g. <c>"primary-dark"</c>), needed so these pages can
    /// render every palette's full swatch set at once — a live <c>var(--fa-*)</c>
    /// read only ever reflects whichever ONE palette is currently active on
    /// <c>&lt;html&gt;</c>. <see cref="Dark"/> holds only the keys that palette's
    /// dark-mode block actually redefines (same set for every palette: cream,
    /// surface, text, text-muted, border, border-focus, footer, primary-dark,
    /// accent-dark, and the three alert-*-bg tokens) — everything else carries
    /// over from <see cref="Light"/> unchanged, same as in <c>_palettes.scss</c>
    /// itself. If a palette's colors change there, update this copy too — they
    /// don't derive from each other automatically.
    /// </summary>
    public sealed record Entry(string Slug, string Title, string Blurb,
        Dictionary<string, string> Light, Dictionary<string, string> Dark);

